const { readFileSync } = require("node:fs");
const { createRequire } = require("node:module");
const { pathToFileURL } = require("node:url");
const load = createRequire("/work/package.json");
const { Parser, HtmlRenderer } = load("commonmark");
const markdownIt = load("markdown-it")("commonmark");

(async () => {
  const { marked } = await import(pathToFileURL("/work/lib/marked.esm.js"));
  const common = new Parser();
  const html = new HtmlRenderer();
  const specs = JSON.parse(readFileSync("/work/test/specs/commonmark/commonmark.0.31.2.json"))
    .filter(row => row.section === "Emphasis and strong emphasis");
  const mismatchedSpec = specs.filter(row => marked.parse(row.markdown, { gfm: false }) !== row.html);
  const observations = { official_examples: specs.length, official_mismatches: mismatchedSpec.map(row => row.example),
    generated: 0, reference_disagreements: 0, differs_from_both: 0, shortest: [] };
  let current = [""];
  for (let length = 1; length <= 6; length++) {
    current = current.flatMap(prefix => ["*", "_", "a", "!"].map(c => prefix + c));
    for (const form of current) {
      if (!form.includes("a") || (form.match(/[*_]/g) || []).length < 2) continue;
      const input = "x " + form + " x";
      const a = html.render(common.parse(input));
      const b = markdownIt.renderInline(input);
      observations.generated++;
      if (a !== "<p>" + b + "</p>\n") {
        observations.reference_disagreements++;
        continue;
      }
      const actual = marked.parseInline(input, { gfm: false });
      if (actual !== b) {
        observations.differs_from_both++;
        observations.shortest.push({ input, expected: b, actual });
      }
    }
  }
  console.log(JSON.stringify(observations));
})().catch(error => { console.error(error); process.exitCode = 1; });

const { createRequire } = require("node:module");
const load = createRequire("/work/package.json");
const { Parser, HtmlRenderer } = load("commonmark");
const markdownIt = load("markdown-it")("commonmark");

(async () => {
  const { marked } = await import("/work/lib/marked.esm.js");
  const parser = new Parser();
  const renderer = new HtmlRenderer();
  const samples = ["a**b*", "!__!_", "_a__!__!", "!_a__!__!", "__a___!__!", "!__a___!__!"];
  const replay = samples.map(input => {
    const expected = markdownIt.renderInline(input);
    if (renderer.render(parser.parse(input)) !== `<p>${expected}</p>\n`) throw Error(input);
    return { input, expected, actual: marked.parseInline(input, { gfm: false }) };
  });
  let forms = [""];
  const groups = { asterisks: [0, 0], underscores: [0, 0], both: [0, 0] };
  for (let len = 1; len <= 6; len++) {
    forms = forms.flatMap(s => ["*", "_", "a", "!"].map(c => s + c));
    for (const form of forms) {
      if (!form.includes("a") || (form.match(/[*_]/g) || []).length < 2) continue;
      const input = "x " + form + " x";
      const expected = markdownIt.renderInline(input);
      if (renderer.render(parser.parse(input)) !== `<p>${expected}</p>\n`) throw Error(input);
      const counts = form.includes("*") ? form.includes("_") ? groups.both : groups.asterisks : groups.underscores;
      counts[0]++;
      counts[1] += Number(marked.parseInline(input, { gfm: false }) !== expected);
    }
  }
  console.log(JSON.stringify({ replay, groups }));
})().catch(error => { console.error(error); process.exitCode = 1; });
